extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	clear_printed()
	var scene := await instantiate_scene("res://basket.tscn")
	if not check("basket_loaded", scene != null, "La scena basket.tscn deve aprirsi senza errori"):
		return
	var basket := scene as Sprite2D
	if not check("basket_type", basket != null, "La radice della scena basket.tscn deve essere uno Sprite2D"):
		return
	check("pos", basket.position == Vector2(576, 600), "Il cesto deve posizionarsi a Vector2(576, 600)")
	check("modulate", basket.modulate == Color.GREEN, "Il cesto deve essere colorato con Color.GREEN")
	check("output", "Cesto pronto:" in printed_text(), "Lo script deve stampare un testo contenente 'Cesto pronto:'")

